# Also longest ORF with ATG start >=50 aa already done. Let's do all ORFs >=30 aa
def orfs(s,minaa=30):
    res=[]
    for frame in range(3):
        start=None
        for j in range(frame, L-2,3):
            cod=s[j:j+3]
            if cod=='ATG' and start is None: start=j
            if cod in ('TAA','TAG','TGA'):
                if start is not None and (j-start)//3>=minaa:
                    res.append((start+1,j+3,(j-start)//3))
                start=None
    return res
